function openEventForm(animalId,eventId,presetType){const e=state.events.find(x=>x.id===eventId);
 if(e?.cancelled){toast('Événement annulé : consulte l’historique des corrections.');return;}
 const {form,close}=modal(e?'Modifier un événement':presetType||'Nouvel événement',`<div class="form-grid"><div class="field"><label>Type d’événement</label><select name="type">${['Observation','Naissance',...TyBufalaReproduction.TYPES,'Saillie','Tarissement','Mise en lactation','Sevrage','Traitement','Vaccination','Intervention','Analyse','Maladie','Blessure','Pesée','Changement de lot','Changement de parcelle','Entrée','Vente','Transfert','Décès','Sortie','Autre'].map(t=>`<option ${(e?.type||presetType)===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Date de l’événement *</label><input type="date" name="date" ${e?.dateUnknown?'':'required'} value="${esc(e?.date||(!e?localToday():''))}"></div><div class="field"><label>Confirmation</label><select name="confirmation">${[['confirmed','Fait confirmé'],['uncertain','À confirmer / historique'],['planned','Prévu']].map(([v,l])=>`<option value="${v}" ${(e?.confirmation||(!e?'confirmed':'uncertain'))===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field" data-repro-result><label>Résultat du diagnostic</label><select name="result"><option value="">Choisir…</option>${[['positive','Pleine'],['negative','Vide'],['uncertain','Indéterminé']].map(([v,l])=>`<option value="${v}" ${e?.result===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field" data-repro-bull><label>Taureau connu (facultatif)</label><select name="bullId"><option value="">Non renseigné / extérieur</option>${state.animals.filter(a=>a.sex==='M').map(a=>`<option value="${esc(a.id)}" ${e?.bullId===a.id?'selected':''}>${esc(displayAnimal(a))} · ${esc(a.earTag)}</option>`).join('')}</select></div><div class="field"><label><input type="checkbox" name="dateUnknown" ${e?.dateUnknown?'checked':''}> Date historique inconnue</label></div><div class="field wide"><label>Détails / observation</label><textarea name="description">${esc(e?.description||'')}</textarea></div><details class="field wide" ${(e?.type||presetType)==='Traitement'?'open':''}><summary>Détails du traitement vétérinaire</summary><div class="form-grid">${['medication','dose','route','prescriber'].map((key,i)=>`<div class="field"><label>${['Médicament','Dose (avec unité)','Voie d’administration','Prescripteur'][i]}</label><input name="${key}" value="${esc(e?.[key]||'')}"></div>`).join('')}${['durationDays','milkWithdrawalDays','meatWithdrawalDays'].map((key,i)=>`<div class="field"><label>${['Durée (jours)','Attente lait (jours)','Attente viande (jours)'][i]}</label><input name="${key}" type="number" inputmode="numeric" min="0" step="1" value="${esc(e?.[key]??'')}"></div>`).join('')}</div></details><div class="field wide"><label>Prochaine date à vérifier (facultatif)</label><input type="date" name="nextDate" value="${esc(e?.nextDate||'')}"><span class="help">Cette date apparaîtra sur l’accueil à partir de 30 jours avant l’échéance, ou si elle est dépassée.</span></div></div>`,e?'Enregistrer':'Ajouter',async form=>{
 const f=new FormData(form),details={};for(const key of ['medication','dose','route','prescriber'])details[key]=String(f.get(key)||'');for(const key of ['durationDays','milkWithdrawalDays','meatWithdrawalDays'])details[key]=f.get(key)===''?null:Number(f.get(key));
 const event={...(e||{}),...details,confirmation:String(f.get('confirmation')),result:['Échographie','Diagnostic de gestation'].includes(String(f.get('type')))?String(f.get('result')||''):'',bullId:['Saillie','Saillie naturelle','Insémination','Mise avec taureau'].includes(String(f.get('type')))?String(f.get('bullId')||''):'',dateUnknown:f.get('dateUnknown')==='on',id:e?.id||makeID('event'),animalId,type:String(f.get('type')||'Observation'),date:String(f.get('date')||''),description:String(f.get('description')||'').trim(),nextDate:String(f.get('nextDate')||''),createdAt:e?.createdAt||nowISO(),updatedAt:nowISO()};
 if(event.dateUnknown)event.date='';
 if(['Échographie','Diagnostic de gestation'].includes(event.type)&&!event.result)throw new Error('Choisis le résultat du diagnostic.');
   const changes=[{kind:'events',data:event}];
   if(event.confirmation==='confirmed'&&!e && ['Tarissement','Mise en lactation'].includes(event.type)){
     const a=animalFor(animalId),nextStatus=event.type==='Tarissement'?'dry':'lactating';
     if(a?.sex==='F'&&a.status==='present'&&event.date&&event.date<=localToday()&&(!a.productionStatusDate||event.date>=a.productionStatusDate)){
       if(confirm(`Cet événement confirme-t-il que ${displayAnimal(a)} est ${nextStatus==='dry'?'actuellement tarie':'actuellement en lactation'} ?`))changes.push({kind:'animals',data:{...a,productionStatus:nextStatus,reproductiveStatus:'calved',productionStatusDate:event.date,updatedAt:nowISO()}});
     }else toast('Événement enregistré sans modifier le statut actuel (date antérieure, future ou animal non concerné).');
   }
 if(event.confirmation==='confirmed'&&event.type==='Vêlage'){
 const a=animalFor(animalId);
 if(a?.sex!=='F')throw new Error('Le vêlage doit être rattaché à une femelle.');
 if(event.date&&event.date<=localToday()&&(!a.lastCalving||event.date>=a.lastCalving)&&confirm('Confirmer le vêlage réel et actualiser la fiche de la mère ?'))changes.push({kind:'animals',data:{...a,lastCalving:event.date,reproductiveStatus:'calved',updatedAt:nowISO()}});
 }
 if(event.confirmation==='confirmed'&&!e&&['Sortie','Entrée'].includes(event.type)){
 const a=animalFor(animalId);
 if(!event.date||event.date>localToday())throw new Error('Une entrée ou sortie effective nécessite une date connue, au plus tard aujourd’hui.');
 if(event.type==='Sortie'&&!event.description)throw new Error('Précise le motif de sortie dans les détails.');
 if(a.exitDate&&event.date<a.exitDate)throw new Error('Cette date précède la dernière sortie : utilise un événement historique sans changer la présence.');
 changes.push({kind:'animals',data:{...a,status:event.type==='Sortie'?'sorti':'present',exitDate:event.type==='Sortie'?event.date:'',exitReason:event.type==='Sortie'?event.description:'',updatedAt:nowISO()}});
 }
 reconcileCalvingCorrection(e,event,changes);
 changes.push(...herdWorkCompletionChanges(event));
 await putGroup(changes);toast('Événement enregistré localement ; historique conservé.');
 });
 const refreshFields=()=>{const type=form.elements.type.value;form.querySelector('[data-repro-result]').hidden=!['Échographie','Diagnostic de gestation'].includes(type);form.querySelector('[data-repro-bull]').hidden=!['Saillie','Saillie naturelle','Insémination','Mise avec taureau'].includes(type);form.elements.date.required=!form.elements.dateUnknown.checked;form.elements.date.disabled=form.elements.dateUnknown.checked;};
 if(e){const cancel=document.createElement('button');cancel.type='button';cancel.className='btn ghost danger-text';cancel.id='cancelEvent';cancel.textContent='Annuler cet événement';form.append(cancel);cancel.onclick=async()=>{try{await cancelAnimalEvent(e);close();render();}catch(error){toast(error.message);}};}
 form.elements.type.addEventListener('change',refreshFields);form.elements.dateUnknown.addEventListener('change',refreshFields);refreshFields();}

function saleTotal(s){return s.lines.reduce((sum,line)=>sum+(Number(line.totalCents)||0),0);}
function renderSales(){const active=state.sales.filter(s=>!s.cancelled);app.innerHTML=`<section class="hero"><p class="eyebrow">Caisse terrain</p><h1>Ventes ponctuelles</h1><p class="lead">Saisir une vente au moment où elle se produit, même sans réseau.</p></section><div class="section-head"><h2>${active.length} ventes saisies</h2><button class="btn small" id="addSale">＋ Vente</button></div>
 <div class="filter-row"><input type="search" id="salesSearch" placeholder="Produit, date, client…" aria-label="Rechercher une vente" value="${esc(ui.salesSearch)}"></div><div id="salesList" class="list"></div><p class="help">Les ventes sont partagées entre les appareils. Leur intégration Windows reste distincte et doit être confirmée par un accusé de réception SQLite.</p>`;
 document.getElementById('addSale').onclick=()=>openSaleForm();document.getElementById('salesSearch').oninput=e=>{ui.salesSearch=e.target.value;drawSalesList();};drawSalesList();}
function drawSalesList(){const q=norm(ui.salesSearch);const items=state.sales.filter(s=>(!q||norm(`${s.date} ${s.client} ${s.channel} ${s.paymentMethod} ${s.lines.map(x=>x.product).join(' ')}`).includes(q))).sort((a,b)=>b.date.localeCompare(a.date)||b.createdAt.localeCompare(a.createdAt));
 document.getElementById('salesList').innerHTML=items.length?items.map(s=>`<div class="list-item"><div><div class="name">${dateFR(s.date)} · ${esc(s.channel)}</div><div class="meta">${esc(s.lines.map(l=>l.product).join(', '))}${s.client?' · '+esc(s.client):''}<br>${esc(s.paymentMethod)} · <span class="badge warn">${s.cancelled?'Annulée · trace conservée':s._sync==='shared'?'Base commune · Windows en attente':'À transmettre'}</span></div></div><div class="right"><div class="amount">${euros(saleTotal(s))}</div><button class="btn ghost small" data-sale="${esc(s.id)}">Modifier</button></div></div>`).join(''):'<div class="empty">Aucune vente enregistrée. Ajoute une vente ponctuelle pour commencer.</div>';
 document.querySelectorAll('#salesList [data-sale]').forEach(b=>b.onclick=()=>openSaleForm(b.dataset.sale));}
function roundLine(price,qty){const total=(BigInt(price)*BigInt(qty)+500n)/1000n;if(total>BigInt(Number.MAX_SAFE_INTEGER))throw new Error('Montant trop élevé.');return Number(total);}
function parseCents(raw){const s=String(raw||'').trim().replace(',','.');if(!/^\d+(\.\d{1,2})?$/.test(s))throw new Error('Le prix TTC doit être un montant positif avec au plus 2 décimales.');const [euros,dec='']=s.split('.');const result=Number(euros)*100+Number(dec.padEnd(2,'0'));if(!Number.isSafeInteger(result))throw new Error('Prix trop élevé.');return result;}
function parseQtyMilli(raw){const s=String(raw||'').trim().replace(',','.');if(!/^\d+(\.\d{1,3})?$/.test(s))throw new Error('La quantité doit être positive (3 décimales maximum).');const [units,dec='']=s.split('.');const val=Number(units)*1000+Number(dec.padEnd(3,'0'));if(!Number.isSafeInteger(val)||val<=0)throw new Error('La quantité doit être supérieure à zéro.');return val;}
const displayQty=milli=>String(milli/1000).replace('.',',');
function saleLineHTML(line,index){const l=line||{};return `<div class="sale-line"><div class="sale-line-head"><strong>Produit ${index+1}</strong><button type="button" class="btn ghost small remove-line" aria-label="Supprimer cette ligne">Supprimer</button></div><div class="form-grid"><div class="field wide"><label>Produit *</label><input name="product" required maxlength="140" placeholder="Ex. Mozzarella 170 g" value="${esc(l.product||'')}"></div><div class="field"><label>Quantité *</label><input name="quantity" type="text" inputmode="decimal" required value="${esc(l.quantityMilli?displayQty(l.quantityMilli):'1')}"></div><div class="field"><label>Unité</label><select name="unit">${['pièce','kg','pot','lot','autre'].map(u=>`<option ${l.unit===u?'selected':''}>${u}</option>`).join('')}</select></div><div class="field"><label>Prix unitaire TTC (€) *</label><input name="price" type="text" inputmode="decimal" required placeholder="0,00" value="${esc(Number.isInteger(l.unitPriceCents)?(l.unitPriceCents/100).toFixed(2).replace('.',','):'')}"></div><div class="field"><label>TVA (si connue)</label><select name="vatRate"><option value="">À déterminer</option>${['0','5.5','10','20'].map(v=>`<option value="${v}" ${String(l.vatRate)===v?'selected':''}>${v.replace('.',',')} %</option>`).join('')}</select></div></div></div>`;}
function openSaleForm(id){const s=state.sales.find(x=>x.id===id);if(s?.cancelled){toast('Vente annulée.');return;}
 const content=`<div class="form-grid"><div class="field"><label>Date de vente *</label><input type="date" name="date" required value="${esc(s?.date||localToday())}"></div><div class="field"><label>Lieu / canal</label><select name="channel">${['Marché','À la ferme','Livraison','Autre'].map(x=>`<option ${s?.channel===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Mode de règlement</label><select name="paymentMethod">${['Espèces','Carte bancaire','Virement','Chèque','Autre'].map(x=>`<option ${s?.paymentMethod===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Client (facultatif)</label><input name="client" maxlength="120" value="${esc(s?.client||'')}"></div></div><div><h3>Produits vendus</h3><div id="lineItems" class="line-items">${(s?.lines?.length?s.lines:[{}]).map(saleLineHTML).join('')}</div><button type="button" id="addLine" class="btn secondary small" style="margin-top:8px">＋ Ajouter un produit</button></div><div class="total" id="saleTotalPreview">Total TTC : —</div><div class="field"><label>Note</label><textarea name="notes">${esc(s?.notes||'')}</textarea></div>${s?'<button class="btn ghost danger-text" type="button" id="cancelSale">Annuler cette vente</button>':''}`;
 const {form,close}=modal(s?'Modifier la vente':'Nouvelle vente',content,s?'Enregistrer':'Enregistrer la vente',async form=>{
 const f=new FormData(form),lines=[];
 for(const [i,row] of [...form.querySelectorAll('.sale-line')].entries()){
  const product=row.querySelector('[name=product]').value.trim();if(!product)throw new Error(`Nom du produit manquant (ligne ${i+1}).`);
  const quantityMilli=parseQtyMilli(row.querySelector('[name=quantity]').value),unitPriceCents=parseCents(row.querySelector('[name=price]').value);
  const rawVat=row.querySelector('[name=vatRate]').value;
  lines.push({product,quantityMilli,unit:row.querySelector('[name=unit]').value,unitPriceCents,vatRate:rawVat===''?null:Number(rawVat),totalCents:roundLine(unitPriceCents,quantityMilli)});
 }
 if(!lines.length)throw new Error('Ajoute au moins un produit.');
 const record={...(s||{}),id:s?.id||makeID('sale'),date:String(f.get('date')||localToday()),channel:String(f.get('channel')||'Autre'),paymentMethod:String(f.get('paymentMethod')||'Autre'),client:String(f.get('client')||'').trim(),notes:String(f.get('notes')||'').trim(),lines,syncState:'pending',cancelled:false,createdAt:s?.createdAt||nowISO(),updatedAt:nowISO()};
 await put('sales',record);toast('Vente sauvegardée sur le téléphone.');
 });
 const linesEl=form.querySelector('#lineItems'),preview=form.querySelector('#saleTotalPreview');
 const recalc=()=>{try{let total=0;for(const row of form.querySelectorAll('.sale-line')){const price=row.querySelector('[name=price]').value,quantity=row.querySelector('[name=quantity]').value;if(!price||!quantity){preview.textContent='Total TTC : —';return;}total+=roundLine(parseCents(price),parseQtyMilli(quantity));}preview.textContent=`Total TTC : ${euros(total)}`;}catch{preview.textContent='Total TTC : à vérifier';}};
 const reindex=()=>[...linesEl.querySelectorAll('.sale-line')].forEach((row,i)=>row.querySelector('.sale-line-head strong').textContent=`Produit ${i+1}`);
 form.querySelector('#addLine').onclick=()=>{linesEl.insertAdjacentHTML('beforeend',saleLineHTML({},linesEl.children.length));recalc();};
 linesEl.addEventListener('click',e=>{if(e.target.closest('.remove-line')){if(linesEl.children.length===1){toast('Une vente doit contenir au moins un produit.');return;}e.target.closest('.sale-line').remove();reindex();recalc();}});
 linesEl.addEventListener('input',recalc);recalc();
 if(s){form.querySelector('#cancelSale').onclick=async()=>{if(!confirm('Annuler cette vente ? Elle restera dans l’historique technique pour éviter des doublons de synchronisation.'))return;try{await put('sales',{...s,cancelled:true,syncState:'pending',updatedAt:nowISO()});close();render();toast('Vente annulée.');}catch(err){toast('Impossible d’annuler : '+err.message);}};}
}
function exportContent(filename,content,mime){const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function snapshot(kind){return {...Object.fromEntries(STORES.map(k=>[k,state[k]])),application:'ty-bufala-mobile',formatVersion:1,kind,exportedAt:nowISO(),source:'mobile',animals:state.animals,events:state.events,sales:state.sales};}
function downloadBackup(){exportContent(`ty-bufala-mobile-sauvegarde-${localToday()}.json`,JSON.stringify(snapshot('backup'),null,2),'application/json;charset=utf-8');toast('Sauvegarde JSON téléchargée.');}
function downloadHandoff(){const pending=state.sales.filter(x=>x.syncState!=='synced');const pack={...snapshot('ty-bufala-import'),sales:pending};exportContent(`ty-bufala-a-importer-${localToday()}.json`,JSON.stringify(pack,null,2),'application/json;charset=utf-8');toast('Fichier préparé. Import dans Ty Bufala non encore connecté.');}
function csvField(v){const s=String(v??'');return /[;\n"\r]/.test(s)?`"${s.replace(/"/g,'""')}"`:s;}
function csv(rows){return '\ufeff'+rows.map(row=>row.map(csvField).join(';')).join('\r\n')+'\r\n';}
function downloadSalesCsv(){const rows=[['vente_id','date','canal','client','reglement','annulee','produit','quantite','unite','prix_unitaire_ttc_eur','montant_ttc_eur','tva_pourcent','date_modification']];
 for(const s of state.sales){for(const l of s.lines){rows.push([s.id,s.date,s.channel,s.client,s.paymentMethod,s.cancelled?'oui':'non',l.product,displayQty(l.quantityMilli),l.unit,(l.unitPriceCents/100).toFixed(2).replace('.',','),(l.totalCents/100).toFixed(2).replace('.',','),l.vatRate??'',s.updatedAt]);}}
 exportContent(`ty-bufala-ventes-${localToday()}.csv`,csv(rows),'text/csv;charset=utf-8');toast('CSV des ventes téléchargé.');}
function downloadHerdCsvTemplate(){const rows=[['boucle','nom','sexe','date_naissance','mere','statut','notes'],['FR0000000000','Exemple à remplacer','F','2025-05-21','','present','']];exportContent('modele-import-cheptel.csv',csv(rows),'text/csv;charset=utf-8');toast('Modèle CSV téléchargé : remplacer la ligne d’exemple.');}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;const src=String(text).replace(/^\ufeff/,'');let delimiter=';';const first=src.split(/\r?\n/)[0]||'';if((first.match(/,/g)||[]).length>(first.match(/;/g)||[]).length)delimiter=',';
 for(let i=0;i<src.length;i++){const c=src[i];if(c==='"'){if(quoted&&src[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===delimiter&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&src[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}
 row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(quoted)throw new Error('CSV : guillemets non fermés.');return rows;}
async function importHerdCsv(file){if(cloud)throw new Error('Import central réservé à l’administrateur après rapprochement.');const rows=parseCSV(await file.text());if(rows.length<2)throw new Error('CSV vide ou sans animaux.');const head=rows[0].map(x=>norm(x).replace(/\s+/g,'_')),
 idx=key=>head.indexOf(key),column=(r,key)=>idx(key)<0?'':String(r[idx(key)]||'').trim();
 if(idx('boucle')<0)throw new Error('La colonne « boucle » manque. Utilise le modèle fourni.');
 const incoming=[],inFile=new Set();for(const [i,r] of rows.slice(1).entries()){
  const earTag=cleanTag(column(r,'boucle'));if(!earTag)continue;if(inFile.has(earTag))throw new Error(`Doublon de boucle dans le CSV (ligne ${i+2}) : ${earTag}`);inFile.add(earTag);
  const existing=state.animals.find(a=>cleanTag(a.earTag)===earTag);
  const birthDate=column(r,'date_naissance');if(birthDate&&!/^\d{4}-\d{2}-\d{2}$/.test(birthDate))throw new Error(`Date non ISO (ligne ${i+2}) : ${birthDate}. Format attendu AAAA-MM-JJ.`);
  const sex=column(r,'sexe').toUpperCase(),status=norm(column(r,'statut'));
  incoming.push({id:existing?.id||makeID('animal'),earTag,name:column(r,'nom')||existing?.name||'',sex:sex==='M'?'M':existing?.sex||'F',birthDate:birthDate||existing?.birthDate||'',motherTag:cleanTag(column(r,'mere'))||existing?.motherTag||'',status:status==='sorti'?'sorti':status==='present'?'present':existing?.status||'present',notes:column(r,'notes')||existing?.notes||'',createdAt:existing?.createdAt||nowISO(),updatedAt:nowISO()});
 }
 if(!incoming.length)throw new Error('Aucun numéro de boucle dans ce fichier.');
 if(!confirm(`Importer ${incoming.length} animaux ? Les numéros existants seront mis à jour, sans supprimer les autres animaux.`))return;
 await dbPutMany('animals',incoming);await reload();render();toast(`${incoming.length} fiche(s) importée(s).`);
}
async function importBackup(file){if(cloud)throw new Error('Restauration centrale contrôlée requise. La sauvegarde locale n’est pas fusionnée automatiquement.');const data=JSON.parse(await file.text());if(data?.application!=='ty-bufala-mobile'||data.formatVersion!==1)throw new Error('Ce fichier ne correspond pas à une sauvegarde Ty Bufala Mobile v1.');
 for(const s of STORES){if(!Array.isArray(data[s])||data[s].some(x=>!x||typeof x!=='object'||typeof x.id!=='string'||!x.id))throw new Error(`Fichier invalide : ${s}.`);}
 if(!confirm('Fusionner cette sauvegarde avec les données de ce téléphone ? Les fiches avec le même identifiant seront remplacées si elles sont plus récentes.'))return;
 for(const store of STORES){const existing=new Map(state[store].map(x=>[x.id,x]));const updates=[];for(const item of data[store]){const current=existing.get(item.id);if(!current||String(item.updatedAt||'')>String(current.updatedAt||''))updates.push(item);}if(updates.length)await dbPutMany(store,updates);}
 await reload();render();toast('Sauvegarde fusionnée.');}
async function renderData(){
 const queue=cloud?await cloud.all('outbox'):[],conflicts=queue.filter(b=>b.blocked);let inventoryStatus;
 if(ui.view!=='data')return;
 app.innerHTML=`<section class="hero"><p class="eyebrow">Compte individuel · ${esc(sessionUser?.role)}</p><h1>Plus</h1><div class="quick-actions"><button class="btn secondary" id="moreLots">Mes lots</button><button class="btn secondary" id="moreSales">Ventes</button></div><p>${esc(sessionUser?.name)} · ${esc(sessionUser?.id)}</p></section>
 <div class="card form-stack"><h2>Synchronisation entre appareils</h2><p>${queue.length} groupe(s) en attente · ${conflicts.length} conflit(s)</p><p role="status">${esc(cloud?.error||(!navigator.onLine?'Hors connexion : saisies conservées dans la file locale.':'Base commune accessible après connexion.'))}</p><button class="btn" id="syncNow">Synchroniser maintenant</button><button class="btn secondary" id="logout">Déconnecter ce compte</button></div>
 ${conflicts.map(b=>`<div class="card"><h2>Modification à vérifier</h2><p>${esc(b.blocked.error)}</p><p>Comparer chaque champ avant de choisir. La version abandonnée restera dans le journal local des conflits.</p><details><summary>Mes données et la version commune</summary><h3>Mes données</h3><pre class="conflict-data">${esc(JSON.stringify(b.operations,null,2))}</pre><h3>Version commune</h3><pre class="conflict-data">${esc(JSON.stringify(b.blocked.current||b.blocked,null,2))}</pre></details>${b.blocked.status===422||b.blocked.code==='duplicate_tag'?`<button class="btn" data-correct="${esc(b.id)}">Corriger la saisie rejetée</button>`:''}<button class="btn secondary" data-resolve="${esc(b.id)}" data-choice="local">Reprendre ma version</button><button class="btn secondary" data-resolve="${esc(b.id)}" data-choice="remote">Conserver la version commune</button></div>`).join('')}
 <button class="tile" id="openQuality"><strong>Contrôles & filiation</strong><span>›</span></button><details class="card"><summary>Source de l’inventaire</summary><div id="inventoryDetails">${inventoryStatus?.imports?.length?inventoryStatus.imports.map(i=>`<p>Import central enregistré le ${esc(i.imported_at)} : ${i.report.animals} animaux identifiés.</p><details><summary>Lignes et filiations à vérifier (${(i.report.anomalies||[]).length})</summary><pre class="conflict-data">${esc(JSON.stringify(i.report.anomalies||[],null,2))}</pre></details>`).join(''):'<p>Import central non enregistré ou statut inaccessible hors connexion.</p>'}</div></details>
 <details class="card"><summary>Sauvegardes & exports</summary><div class="form-stack"><button class="btn secondary" id="backup">Sauvegarder cet appareil et sa file d’attente</button><button class="btn secondary" id="centralBackup">${sessionUser?.role==='admin'?'Sauvegarde centrale complète':'Exporter mes données accessibles'}</button><button class="btn secondary" id="handoff">Exporter pour Windows (sans accusé de réception)</button><p class="help">Les exports de fichiers ne sont pas des confirmations de synchronisation.</p></div></details>`;
 document.getElementById('openQuality').onclick=()=>nav('quality');
 cloud.request('inventory-status').then(info=>{const target=document.getElementById('inventoryDetails');if(target)target.innerHTML=(info.imports||[]).map(i=>`<p>${esc(i.report.animals)} animaux · ${esc(i.imported_at)}</p><details><summary>Filiations et lignes à vérifier (${(i.report.anomalies||[]).length})</summary><pre class="conflict-data">${esc(JSON.stringify(i.report.anomalies||[],null,2))}</pre></details>`).join('')||'<p>Aucun import central enregistré.</p>';}).catch(()=>{});
 document.getElementById('moreLots').onclick=()=>nav('lots');document.getElementById('moreSales').onclick=()=>nav('sales');
 document.getElementById('syncNow').onclick=()=>cloud.run();document.getElementById('backup').onclick=async()=>{const pack={...snapshot('backup'),outbox:await cloud.all('outbox'),conflicts:await cloud.all('conflicts')};exportContent('ty-bufala-sauvegarde-'+localToday()+'.json',JSON.stringify(pack,null,2),'application/json');};
 document.getElementById('centralBackup').onclick=async()=>{try{const pack=await cloud.request('export');exportContent('ty-bufala-base-commune-'+localToday()+'.json',JSON.stringify(pack,null,2),'application/json');}catch(e){toast(e.message);}};
 document.getElementById('handoff').onclick=downloadHandoff;
 document.getElementById('logout').onclick=async()=>{if((await cloud.all('outbox')).length){toast('Synchronise ou résous les opérations avant de déconnecter ce compte.');return;}try{await cloud.request('logout',{method:'POST',body:'{}'});database.close();indexedDB.deleteDatabase(DB_NAME);localStorage.removeItem('tb-active-user');location.reload();}catch(e){toast(e.message);}};
 app.querySelectorAll('[data-correct]').forEach(b=>b.onclick=()=>{const batch=conflicts.find(x=>x.id===b.dataset.correct),operation=batch.operations.find(o=>o.opId===batch.blocked.opId)||batch.operations[0];if(operation.kind==='animals')openAnimalForm(operation.data.id);else if(operation.kind==='events')openEventForm(operation.data.animalId,operation.data.id);else if(operation.kind==='sales')openSaleForm(operation.data.id);else toast('Affectation rejetée : compare les versions puis conserve la base commune avant de refaire l’action.');});
 app.querySelectorAll('[data-resolve]').forEach(b=>b.onclick=async()=>{if(!confirm(b.dataset.choice==='local'?'Après comparaison, remplacer la version commune par les données locales de ce groupe ?':'Conserver la version commune et archiver les modifications locales liées (y compris les groupes dépendants) ?'))return;try{await cloud.resolve(b.dataset.resolve,b.dataset.choice);await reload();render();}catch(e){toast(e.message);}});
}
function showLogin(message=''){
 document.querySelector('.bottom-nav').hidden=true;
 app.innerHTML=`<section class="hero"><h1>Ton cheptel partagé</h1><p>Connecte-toi avec ton compte individuel pour retrouver l’inventaire sur cet appareil.</p></section><form id="loginForm" class="card form-stack"><div class="field"><label for="username">Identifiant individuel</label><input id="username" name="username" autocomplete="username" required></div><div class="field"><label for="password" id="loginSecretLabel">Code personnel à 4 chiffres</label><input id="password" name="password" type="password" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" autocomplete="current-password" required><button type="button" class="btn ghost small" id="loginMode">Utiliser un mot de passe</button></div><p class="help">Connexion conservée 30 jours sur cet appareil. Utilise Déconnecter sur un appareil partagé.</p><p role="alert" id="loginError">${esc(message)}</p><button class="btn" type="submit">Se connecter</button></form>`;
 const rememberedName=localStorage.getItem('tb-login-name')||'';document.getElementById('username').value=rememberedName;
 document.getElementById('loginMode').onclick=()=>{const input=document.getElementById('password'),pin=input.hasAttribute('maxlength');input.value='';document.getElementById('loginSecretLabel').textContent=pin?'Mot de passe':'Code personnel à 4 chiffres';document.getElementById('loginMode').textContent=pin?'Utiliser un code à 4 chiffres':'Utiliser un mot de passe';if(pin){input.removeAttribute('maxlength');input.removeAttribute('pattern');input.inputMode='text';}else{input.maxLength=4;input.pattern='[0-9]{4}';input.inputMode='numeric';}input.focus();};
 document.getElementById('loginForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{const f=new FormData(e.target),response=await fetch('/api/login',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify(Object.fromEntries(f))}),data=await response.json();if(!response.ok)throw new Error(data.error);localStorage.setItem('tb-login-name',String(f.get('username')||'').trim());await activateSession(data);}catch(error){document.getElementById('loginError').textContent=error.message;}finally{button.disabled=false;}};
}
async function activateSession(data){
 sessionUser=data.user;localStorage.setItem('tb-active-user',JSON.stringify(sessionUser));DB_NAME='ty-bufala-cloud-'+sessionUser.id;
 database=await dbOpen();cloud=new CloudSync(database,sessionUser,data.csrf);cloud.onchange=async()=>{await reload();if(!modalRoot.childElementCount){const disclosureKey=el=>(el.closest('[data-timeline-id]')?.dataset.timelineId||'page')+'|'+(el.querySelector('summary')?.textContent||''),opened=new Set([...app.querySelectorAll('details[open]')].map(disclosureKey));const focused=document.activeElement,focusId=focused?.id,selection=focused?.tagName==='INPUT'&&['text','search'].includes(focused.type)?[focused.selectionStart,focused.selectionEnd]:null,scroll=window.scrollY;render();for(const detail of app.querySelectorAll('details'))if(opened.has(disclosureKey(detail)))detail.open=true;const replacement=focusId&&document.getElementById(focusId);if(replacement){replacement.focus({preventScroll:true});if(selection)replacement.setSelectionRange(...selection);}window.scrollTo({top:scroll,behavior:'instant'});}};
 await reload();document.querySelector('.bottom-nav').hidden=false;render();await cloud.run();
 if(!window.tbTimer)window.tbTimer=setInterval(()=>{if(cloud&&!modalRoot.childElementCount)cloud.run();},30000);
}
async function start(){
 try{
 if(!('indexedDB' in window))throw new Error('Stockage local indisponible.');
 document.querySelectorAll('.bottom-nav button').forEach(b=>b.addEventListener('click',()=>nav(b.dataset.view)));
 window.addEventListener('online',()=>cloud?.run());window.addEventListener('offline',render);
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modalRoot.childElementCount){modalRoot.innerHTML='';document.body.style.overflow='';}});
 if('serviceWorker' in navigator)await navigator.serviceWorker.register('./sw.js').catch(()=>{});
 if(!navigator.onLine){const previous=JSON.parse(localStorage.getItem('tb-active-user')||'null');if(previous){await activateSession({user:previous});return;}showLogin('Une première connexion en ligne est nécessaire.');return;}
 const response=await fetch('/api/session',{credentials:'same-origin',cache:'no-store'});
 if(response.ok)await activateSession(await response.json());else{const error=await response.json().catch(()=>({}));if(response.status!==401)throw new Error(error.error||'Serveur temporairement indisponible.');showLogin('Session expirée : reconnecte-toi pour synchroniser.');}

 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')cloud?.run();});
 }catch(error){const previous=JSON.parse(localStorage.getItem('tb-active-user')||'null');if(previous&&!sessionUser){await activateSession({user:previous});cloud.error='Serveur inaccessible : copie hors connexion, session à vérifier.';render();}else showLogin(error.message);}
}
start();
